class Widget {
  constructor(public name: string, public config: any) {}
  clone(): Widget {
    return new Widget(this.name, { ...this.config });
  }
}
const original = new Widget('report', { size: 'A4' });
const copy = original.clone();

const prototypeRegistry: Record<string, any> = {};
prototypeRegistry['report'] = { type: 'report', settings: { size: 'A4' } };

function createFromPrototype(key: string, overrides: any) {
  const proto = prototypeRegistry[key];
  return Object.assign(Object.create(proto), overrides);
}

const r = createFromPrototype('report', { settings: { size: 'A3' } });

// Version A: exemplar clones
class Template {
  constructor(public props: any) {}
  clone(overrides = {}) {
    return Object.assign(Object.create(Object.getPrototypeOf(this)), { ...this.props, ...overrides });
  }
}
const exemplar = new Template({ heavy: true });
const a = exemplar.clone({ heavy: false });

